<div class="container page-content">
    <?php gg_realm_filter('status',$realms,$realmId); ?>
    <div class="page-intro"><div><h2><?php echo $escape($selectedRealm['realmname'] ?? 'Realm'); ?></h2><p>Realm heartbeat and adventurers currently in Azeroth.</p></div><a class="btn btn-ghost" href="<?php echo $escape(gg_url('status',['realm'=>$realmId])); ?>">Refresh status ↻</a></div>
    <?php if (empty($realmSummary['available'])) { gg_empty($realmSummary); } else { ?>
    <div class="metric-grid"><div class="tavern-panel"><span class="stat-label">Worldserver</span><strong class="status-word"><span class="status-dot <?php echo $escape($realmSummary['state']); ?>"></span><?php echo ucfirst($realmSummary['state']); ?></strong><span class="metric-note">Last heartbeat <?php echo $realmSummary['reported_at'] ? gmdate('d M, H:i',$realmSummary['reported_at']) . ' UTC' : 'unavailable'; ?></span></div><div class="tavern-panel"><span class="stat-label">Players online</span><strong><?php echo $showOnlinePlayers ? number_format($realmSummary['online']) : '—'; ?></strong><span class="metric-note">Characters, including playerbots</span></div><div class="tavern-panel"><span class="stat-label">Reported uptime</span><strong><?php echo gg_duration($realmSummary['uptime']); ?></strong><span class="metric-note">Current worldserver session</span></div><div class="tavern-panel"><span class="stat-label">Session peak</span><strong><?php echo $showOnlinePlayers ? number_format($realmSummary['peak']) : '—'; ?></strong><span class="metric-note">Players online at peak</span></div></div>
    <?php if ($showOnlinePlayers) { ?><div class="faction-summary"><span class="alliance-text">Alliance <strong><?php echo number_format($realmSummary['alliance']); ?></strong></span><div class="faction-bar"><span style="width:<?php echo $realmSummary['alliance']+$realmSummary['horde'] > 0 ? round(100*$realmSummary['alliance']/($realmSummary['alliance']+$realmSummary['horde']),2) : 50; ?>%"></span></div><span class="horde-text"><strong><?php echo number_format($realmSummary['horde']); ?></strong> Horde</span></div><?php } ?>
    <p class="data-caption">Status follows the worldserver’s reported heartbeat. A heartbeat older than <?php echo (int) (get_config('realm_heartbeat_grace') ?: 1200) / 60; ?> minutes is shown as offline. All times are UTC.</p>
    <?php } ?>
    <section class="tavern-panel ranking-panel"><div class="panel-title"><h3>Who’s in Azeroth</h3><span class="table-caption">Up to 100 online characters</span></div>
        <?php $online = $selectedRealm ? realm_stats::online_players($realmId) : ['available'=>false]; if (empty($online['rows'])) { gg_empty($online,'A quiet moment in the tavern.','No characters are currently recorded as online.'); } else { ?><div class="table-responsive"><table class="table leaderboard"><thead><tr><th>Character</th><th>Faction</th><th>Class</th><th>Level</th></tr></thead><tbody><?php foreach ($online['rows'] as $character) { ?><tr><th scope="row"><?php echo $escape($character['name']); ?></th><td class="<?php echo strtolower(gg_faction($character['race'])); ?>-text"><?php echo gg_faction($character['race']); ?></td><td><?php echo $escape(gg_classes()[(int)$character['class']] ?? 'Unknown'); ?></td><td><?php echo (int)$character['level']; ?></td></tr><?php } ?></tbody></table></div><?php } ?>
    </section>
</div>
